import { getProfile, homeFor } from "@/lib/auth";
import { redirect } from "next/navigation";

const landingStyles = `
@font-face{font-family:'Inter';font-style:normal;font-weight:400;font-display:swap;src:url(data:font/woff2;base64,) format('woff2');}
@font-face{font-family:'Inter';font-style:normal;font-weight:500;font-display:swap;src:url(data:font/woff2;base64,) format('woff2');}
@font-face{font-family:'Inter';font-style:normal;font-weight:600;font-display:swap;src:url(data:font/woff2;base64,) format('woff2');}
@font-face{font-family:'Inter';font-style:normal;font-weight:700;font-display:swap;src:url(data:font/woff2;base64,) format('woff2');}
@font-face{font-family:'Fraunces';font-style:normal;font-weight:400;font-display:swap;src:url(data:font/woff2;base64,) format('woff2');}
@font-face{font-family:'Fraunces';font-style:normal;font-weight:600;font-display:swap;src:url(data:font/woff2;base64,) format('woff2');}
@font-face{font-family:'Fraunces';font-style:normal;font-weight:700;font-display:swap;src:url(data:font/woff2;base64,) format('woff2');}
:root{
  --ink:#0F1B2D; --ink-soft:#1C2A3E; --ink-muted:#2B3A52;
  --ivory:#F8F5EF; --ivory-deep:#EFEAE0;
  --champagne:#C6A664; --champagne-soft:#D8BE86;
  --teal:#5FB3A8; --teal-soft:#8ECBC2;
  --slate:#5B6678; --slate-soft:#8A93A1;
  --warn:#C9793B; --danger:#B4463C;
  --pill:999px; --card:20px;
  --shadow:0 1px 2px rgba(15,27,45,.04),0 10px 30px rgba(15,27,45,.07);
  --lift:0 18px 50px rgba(15,27,45,.14);
  --maxw:1160px;
}
*{box-sizing:border-box;margin:0;padding:0}
html{scroll-behavior:smooth;-webkit-font-smoothing:antialiased;text-rendering:optimizeLegibility}
body{font-family:'Inter',system-ui,sans-serif;color:var(--ink);background:var(--ivory);line-height:1.55;overflow-x:hidden}
.display{font-family:'Fraunces',Georgia,serif;font-weight:600;line-height:1.08;letter-spacing:-.01em}
a{color:inherit;text-decoration:none}
img{display:block;max-width:100%}
.wrap{max-width:var(--maxw);margin:0 auto;padding:0 24px}
.eyebrow{font-size:12.5px;font-weight:600;letter-spacing:.14em;text-transform:uppercase;color:var(--champagne)}
.eyebrow.dark{color:var(--champagne)}
.muted{color:var(--slate)}

/* buttons */
.btn{display:inline-flex;align-items:center;justify-content:center;gap:9px;border-radius:var(--pill);padding:13px 24px;font-size:14.5px;font-weight:600;transition:transform .15s ease,background .2s ease,box-shadow .2s ease;cursor:pointer;border:none;white-space:nowrap}
.btn:hover{transform:translateY(-1px)}
.btn-primary{background:var(--ink);color:var(--ivory)}
.btn-primary:hover{background:var(--ink-soft)}
.btn-accent{background:var(--champagne);color:var(--ink)}
.btn-accent:hover{background:var(--champagne-soft)}
.btn-ghost{background:transparent;color:var(--ink);border:1.5px solid rgba(15,27,45,.18)}
.btn-ghost:hover{background:rgba(15,27,45,.05)}
.btn-ghost-light{background:transparent;color:var(--ivory);border:1.5px solid rgba(248,245,239,.3)}
.btn-ghost-light:hover{background:rgba(248,245,239,.1)}
.btn-sm{padding:10px 18px;font-size:13px}

/* nav */
header{position:sticky;top:0;z-index:50;background:rgba(248,245,239,.85);backdrop-filter:blur(12px);border-bottom:1px solid rgba(15,27,45,.07)}
nav{display:flex;align-items:center;gap:18px;height:68px}
.brand{display:flex;align-items:center;gap:9px;font-weight:700;font-size:18px;letter-spacing:-.02em}
.brand img{height:26px;width:auto}
.navlinks{display:flex;gap:26px;margin-left:30px}
.navlinks a{font-size:14px;color:var(--ink-muted);font-weight:500}
.navlinks a:hover{color:var(--ink)}
.navright{margin-left:auto;display:flex;align-items:center;gap:12px}
.navright .signin{font-size:14px;font-weight:600;color:var(--ink)}

/* hero */
.hero{padding:62px 0 72px;position:relative}
.hero-grid{display:grid;grid-template-columns:1.02fr .98fr;gap:52px;align-items:center}
.hero h1{font-size:60px;margin:18px 0 0}
.hero .lede{font-size:18.5px;color:var(--slate);margin-top:22px;max-width:480px}
.hero-cta{display:flex;gap:13px;margin-top:30px;flex-wrap:wrap}
.hero-trust{display:flex;gap:22px;margin-top:28px;flex-wrap:wrap}
.hero-trust .t{display:flex;align-items:center;gap:8px;font-size:13px;color:var(--slate);font-weight:500}
.hero-trust .dot{width:7px;height:7px;border-radius:50%;background:var(--teal)}
.hero-media{position:relative}
.hero-media .photo{border-radius:28px;overflow:hidden;box-shadow:var(--lift);aspect-ratio:4/4.4;background:var(--ivory-deep) center/cover}
.hero-media .photo img{width:100%;height:100%;object-fit:cover}
.floatcard{position:absolute;background:#fff;border-radius:16px;box-shadow:var(--lift);padding:13px 16px;display:flex;align-items:center;gap:11px}
.floatcard.one{left:-26px;top:40px}
.floatcard.two{right:-20px;bottom:46px}
.floatcard .ic{width:38px;height:38px;border-radius:11px;display:flex;align-items:center;justify-content:center;flex:0 0 auto}
.floatcard .t{font-weight:600;font-size:13px}
.floatcard .s{font-size:11.5px;color:var(--slate)}

/* generic section */
section.band{padding:78px 0}
.sec-head{max-width:620px}
.sec-head h2{font-size:38px;margin-top:12px}
.sec-head p{font-size:16.5px;color:var(--slate);margin-top:14px}
.center{margin-left:auto;margin-right:auto;text-align:center}

/* pillars */
.pillars{display:grid;grid-template-columns:repeat(3,1fr);gap:22px;margin-top:44px}
.pillar{background:#fff;border-radius:var(--card);box-shadow:var(--shadow);overflow:hidden;border:1px solid rgba(15,27,45,.05);display:flex;flex-direction:column}
.pillar .ph{height:150px;background:var(--ivory-deep) center/cover;position:relative}
.pillar .ph img{width:100%;height:100%;object-fit:cover}
.pillar .ph:after{content:"";position:absolute;inset:0;background:linear-gradient(180deg,rgba(15,27,45,0) 40%,rgba(15,27,45,.28))}
.pillar .body{padding:22px 22px 26px}
.pillar .ico{width:44px;height:44px;border-radius:12px;display:flex;align-items:center;justify-content:center;margin:-42px 0 14px;position:relative;z-index:2;background:var(--champagne);box-shadow:var(--shadow)}
.pillar h3{font-size:20px;font-family:'Fraunces',serif;font-weight:600}
.pillar p{font-size:14px;color:var(--slate);margin-top:8px}
.plist{margin-top:14px;display:flex;flex-direction:column;gap:9px}
.plist .li{display:flex;gap:9px;font-size:13.5px;align-items:flex-start}
.plist .li svg{flex:0 0 auto;margin-top:2px}

/* journey steps */
.journey{margin-top:46px;position:relative}
.steps{display:grid;grid-template-columns:repeat(4,1fr);gap:18px}
.step{position:relative}
.step .num{width:40px;height:40px;border-radius:50%;background:var(--ink);color:var(--ivory);display:flex;align-items:center;justify-content:center;font-family:'Fraunces',serif;font-weight:600;font-size:17px}
.step h4{font-size:17px;margin-top:16px;font-family:'Fraunces',serif;font-weight:600}
.step p{font-size:13.5px;color:var(--slate);margin-top:6px}
.step .conn{position:absolute;top:20px;left:52px;right:-9px;height:2px;background:repeating-linear-gradient(90deg,rgba(15,27,45,.2) 0 6px,transparent 6px 12px)}
.step:last-child .conn{display:none}

/* quality band */
.quality{background:var(--ink);color:var(--ivory);border-radius:28px;overflow:hidden;display:grid;grid-template-columns:1fr 1fr;align-items:stretch}
.quality .copy{padding:52px 48px}
.quality h2{font-size:34px}
.quality p{color:rgba(248,245,239,.72);margin-top:16px;font-size:16px;max-width:430px}
.qchips{display:flex;gap:10px;flex-wrap:wrap;margin-top:24px}
.qchip{display:inline-flex;align-items:center;gap:8px;background:rgba(248,245,239,.1);border:1px solid rgba(248,245,239,.16);border-radius:var(--pill);padding:9px 15px;font-size:13px;font-weight:500}
.quality .media{background:var(--ink-soft) center/cover;min-height:340px}
.quality .media img{width:100%;height:100%;object-fit:cover;opacity:.92}

/* vendor band */
.vendor{background:linear-gradient(165deg,#14233a,#0F1B2D 60%);color:var(--ivory);position:relative;overflow:hidden}
.vendor:before{content:"";position:absolute;top:-120px;right:-80px;width:360px;height:360px;border-radius:50%;background:radial-gradient(circle,rgba(198,166,100,.22),transparent 70%)}
.vendor .vhead{display:grid;grid-template-columns:1.1fr .9fr;gap:40px;align-items:end;position:relative;z-index:2}
.vendor h2{font-size:40px}
.vendor .vsub{color:rgba(248,245,239,.72);font-size:16.5px;margin-top:16px;max-width:460px}
.vpillars{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;margin-top:46px;position:relative;z-index:2}
.vcard{background:rgba(248,245,239,.055);border:1px solid rgba(248,245,239,.12);border-radius:var(--card);padding:26px 24px}
.vcard .ico{width:46px;height:46px;border-radius:12px;background:rgba(198,166,100,.18);display:flex;align-items:center;justify-content:center;margin-bottom:16px}
.vcard h3{font-size:20px;font-family:'Fraunces',serif;font-weight:600}
.vcard p{font-size:14px;color:rgba(248,245,239,.68);margin-top:9px}
.vlist{margin-top:15px;display:flex;flex-direction:column;gap:9px}
.vlist .li{display:flex;gap:9px;font-size:13.5px;color:rgba(248,245,239,.9);align-items:flex-start}
.vlist .li svg{flex:0 0 auto;margin-top:2px}
.vjourney{margin-top:50px;position:relative;z-index:2}
.vjourney .jh{font-size:13px;letter-spacing:.14em;text-transform:uppercase;color:rgba(248,245,239,.6);font-weight:600}
.vsteps{display:grid;grid-template-columns:repeat(5,1fr);gap:14px;margin-top:22px}
.vstep{background:rgba(248,245,239,.04);border:1px solid rgba(248,245,239,.1);border-radius:16px;padding:18px 16px}
.vstep .n{font-family:'Fraunces',serif;font-weight:600;color:var(--champagne);font-size:15px}
.vstep h4{font-size:15px;margin-top:8px}
.vstep p{font-size:12.5px;color:rgba(248,245,239,.62);margin-top:5px}
.vcta{display:flex;align-items:center;gap:16px;margin-top:42px;flex-wrap:wrap;position:relative;z-index:2}

/* ===== full app screens in journey steps (UI reference, scoped to .app) ===== */
.app{display:flex;justify-content:center;width:100%}
.app .desktop{width:100%;max-width:640px;height:auto;min-height:400px;background:#fff;border-radius:14px;box-shadow:var(--lift);overflow:hidden;display:flex;flex-direction:column;border:1px solid rgba(15,27,45,.08)}
.app .winbar{height:34px;background:var(--ivory);border-bottom:1px solid rgba(15,27,45,.08);display:flex;align-items:center;gap:7px;padding:0 14px;flex:0 0 auto}
.app .winbar .d{width:10px;height:10px;border-radius:50%}
.app .winbar .url{margin-left:12px;font-size:11px;color:var(--slate);background:#fff;border:1px solid rgba(15,27,45,.1);border-radius:var(--pill);padding:3px 14px}
.app .winbody{flex:1;display:flex;min-height:0}
.app .tablet{height:auto;width:100%;max-width:620px;aspect-ratio:4/3;background:var(--ink);border-radius:22px;padding:12px;box-shadow:var(--lift);display:flex}
.app .tablet .screen{flex:1;background:var(--ivory);border-radius:12px;overflow:hidden;display:flex;flex-direction:column}
.app .phone{width:300px;height:640px;background:var(--ink);border-radius:34px;padding:9px;box-shadow:var(--lift);flex:0 0 auto}
.app .phone .screen{width:100%;height:100%;background:var(--ivory);border-radius:27px;overflow:hidden;position:relative;display:flex;flex-direction:column}
.app .phone .notch{position:absolute;top:0;left:50%;transform:translateX(-50%);width:120px;height:20px;background:var(--ink);border-radius:0 0 14px 14px;z-index:5}
.app .sidebar{width:168px;background:var(--ink);color:#fff;flex:0 0 auto;padding:16px 12px;display:flex;flex-direction:column;gap:2px}
.app .sidebar .logo{display:flex;align-items:center;gap:7px;padding:6px 8px 14px}
.app .sidebar .logo img{height:19px}
.app .sidebar .logo span{font-weight:600;font-size:14px}
.app .navitem{font-size:12px;color:rgba(248,245,239,.62);padding:7px 10px;border-radius:9px}
.app .navitem.active{background:rgba(248,245,239,.12);color:#fff;font-weight:500}
.app .navitem.badge{display:flex;justify-content:space-between;align-items:center}
.app .navitem .b{background:var(--warn);color:#fff;font-size:10px;border-radius:var(--pill);padding:1px 7px}
.app .sidebar .me{margin-top:auto;font-size:11px;color:rgba(248,245,239,.5);padding:8px;border-top:1px solid rgba(248,245,239,.12)}
.app .main{flex:1;min-width:0;background:var(--ivory);padding:20px 22px;overflow:hidden}
.app .main h1{font-family:'Fraunces',serif;font-size:22px;font-weight:600}
.app .main .sub{color:var(--slate);font-size:12px;margin-top:3px}
.app .card{background:#fff;border-radius:var(--card);box-shadow:var(--shadow);border:1px solid rgba(15,27,45,.05)}
.app .row{display:flex;align-items:center;justify-content:space-between}
.app .muted{color:var(--slate)}
.app .tiny{font-size:11px;color:var(--slate)}
.app .lbl{font-size:11px;font-weight:600;color:var(--slate);display:block;margin-bottom:5px}
.app .field{border:1px solid rgba(15,27,45,.15);background:#fff;border-radius:11px;padding:8px 11px;font-size:12px;color:var(--ink);display:flex;align-items:center}
.app .field.ph{color:var(--slate-soft)}
.app .btn{display:inline-flex;align-items:center;justify-content:center;gap:6px;border-radius:var(--pill);padding:9px 16px;font-size:12.5px;font-weight:500}
.app .btn-primary{background:var(--ink);color:var(--ivory)}
.app .btn-accent{background:var(--champagne);color:var(--ink)}
.app .btn-ghost{background:transparent;color:var(--ink);border:1px solid rgba(15,27,45,.15)}
.app .chip{display:inline-flex;align-items:center;gap:5px;border-radius:var(--pill);padding:3px 10px;font-size:11px;font-weight:500}
.app .chip-ok{background:rgba(95,179,168,.15);color:var(--teal)}
.app .chip-warn{background:rgba(201,121,59,.15);color:var(--warn)}
.app .chip-muted{background:rgba(91,102,120,.12);color:var(--slate)}
.app .chip-ink{background:rgba(15,27,45,.1);color:var(--ink)}
.app .stars{color:var(--champagne);font-size:12px;letter-spacing:1px}
.app .tbl{width:100%;border-collapse:collapse;font-size:12px}
.app .tbl thead th{text-align:left;font-size:10.5px;color:var(--slate);font-weight:500;padding:9px 12px;background:rgba(15,27,45,.04)}
.app .tbl tbody td{padding:9px 12px;border-top:1px solid rgba(15,27,45,.06)}
.app .tbl tbody td.f{font-weight:500}
.app .stat{background:#fff;border-radius:var(--card);box-shadow:var(--shadow);border:1px solid rgba(15,27,45,.05);padding:13px 14px}
.app .stat .k{font-size:10.5px;color:var(--slate)}
.app .stat .v{font-family:'Fraunces',serif;font-size:22px;font-weight:600;margin-top:3px}
.app .stat .delta{font-size:10px;color:var(--teal);margin-top:2px}
.app .line{height:1px;background:rgba(15,27,45,.1);margin:10px 0}
.app .tl{position:relative;padding-left:22px}
.app .tl:before{content:"";position:absolute;left:7px;top:4px;bottom:4px;width:2px;background:rgba(15,27,45,.1)}
.app .tl .ev{position:relative;padding:0 0 13px}
.app .tl .ev .dot{position:absolute;left:-19px;top:1px;width:12px;height:12px;border-radius:50%;background:#fff;border:2px solid var(--slate-soft)}
.app .tl .ev.done .dot{background:var(--teal);border-color:var(--teal)}
.app .tl .ev.now .dot{background:var(--champagne);border-color:var(--champagne)}
.app .tl .ev .t{font-size:12px;font-weight:500}
.app .tl .ev .s{font-size:10.5px;color:var(--slate)}
.app .itemrow{display:flex;justify-content:space-between;align-items:center;padding:9px 11px}
.app .hr{height:1px;background:rgba(15,27,45,.06)}
.app .grid2{display:grid;grid-template-columns:1fr 1fr;gap:8px}
.app .grid4{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}
.app .stggrid{display:grid;grid-template-columns:1fr 1fr;gap:7px}
.app .stgbtn{border:1px solid rgba(15,27,45,.15);border-radius:11px;padding:8px;text-align:center;font-size:11px;background:#fff}
.app .stgbtn.on{background:var(--ink);color:#fff;border-color:var(--ink)}
.app .pin{font-family:'Fraunces',serif;font-size:22px;letter-spacing:3px;font-weight:600}
.app .mono{font-family:ui-monospace,Menlo,monospace}

/* journey rows */
.jrow{display:grid;grid-template-columns:1fr 1fr;gap:48px;align-items:center;margin-bottom:56px}
.jrow:last-child{margin-bottom:0}
.jrow.rev .jdevice{order:2}
.jdevice{display:flex;justify-content:center;min-width:0}
.jcopy .num{width:40px;height:40px;border-radius:50%;background:var(--ink);color:var(--ivory);display:inline-flex;align-items:center;justify-content:center;font-family:'Fraunces',serif;font-weight:600;font-size:17px}
.jcopy h3{font-size:30px;margin-top:16px}
.jcopy p{font-size:16px;color:var(--slate);margin-top:14px;max-width:420px}
.vjourney .jrow{grid-template-columns:1.3fr 1fr}
.vendor .jcopy h3{color:var(--ivory)}
.vendor .jcopy p{color:rgba(248,245,239,.72)}
.vendor .jcopy .num{background:var(--champagne);color:var(--ink)}
@media(max-width:900px){
  .jrow,.vjourney .jrow{grid-template-columns:1fr;gap:26px;margin-bottom:42px}
  .jrow.rev .jdevice{order:0}
}
@media(max-width:560px){
  .app .sidebar{display:none}
  .app .tablet{max-width:100%}
  .app .phone{transform:scale(.95)}
}

/* ===== punch: 3D tilt + glow + scroll reveal ===== */
.jdevice{perspective:1500px}
.app{transition:transform .6s cubic-bezier(.2,.7,.2,1)}
.jrow:not(.rev) .app{transform:rotateY(-7deg) rotateX(2deg)}
.jrow.rev .app{transform:rotateY(7deg) rotateX(2deg)}
.jrow .app:hover{transform:rotateY(0deg) rotateX(0deg) scale(1.03)}
.jcopy .num{box-shadow:0 6px 18px rgba(15,27,45,.18)}
/* glow behind the screens on the dark partner band */
.vendor .jdevice{position:relative}
.vendor .jdevice::before{content:"";position:absolute;inset:-8% -6%;background:radial-gradient(60% 55% at 50% 42%,rgba(198,166,100,.16),transparent 70%);filter:blur(10px);z-index:0}
.vendor .jdevice>*{position:relative;z-index:1}
.vendor .jcopy .num{box-shadow:0 8px 22px rgba(198,166,100,.34)}
/* scroll reveal (enabled by JS; no-JS keeps everything visible) */
.reveal-on .jrow{opacity:0;transform:translateY(40px);transition:opacity .7s ease,transform .8s cubic-bezier(.2,.7,.2,1)}
.reveal-on .jrow.in{opacity:1;transform:none}
@media (prefers-reduced-motion: reduce){
  .reveal-on .jrow{opacity:1 !important;transform:none !important}
  .app,.jrow:not(.rev) .app,.jrow.rev .app{transform:none !important}
}
@media(max-width:560px){
  .jrow:not(.rev) .app,.jrow.rev .app{transform:none}
}

/* final cta */
.final{text-align:center;padding:88px 0}
.final h2{font-size:44px;max-width:640px;margin:0 auto}
.final p{font-size:17px;color:var(--slate);margin-top:16px}
.final .fcta{display:flex;gap:14px;justify-content:center;margin-top:30px;flex-wrap:wrap}
.final .partner{margin-top:20px;font-size:14px;color:var(--slate)}
.final .partner a{color:var(--ink);font-weight:600;text-decoration:underline;text-underline-offset:3px}

/* footer */
footer{background:var(--ink);color:rgba(248,245,239,.72);padding:54px 0 30px}
.fgrid{display:grid;grid-template-columns:1.4fr 1fr 1fr 1fr;gap:30px}
.fcol h5{color:var(--ivory);font-size:13px;letter-spacing:.08em;text-transform:uppercase;margin-bottom:14px}
.fcol a{display:block;font-size:14px;color:rgba(248,245,239,.65);margin-bottom:9px}
.fcol a:hover{color:var(--ivory)}
.fbrand{display:flex;align-items:center;gap:9px;font-weight:700;font-size:18px;color:var(--ivory)}
.fbrand img{height:24px}
.fbot{border-top:1px solid rgba(248,245,239,.12);margin-top:40px;padding-top:22px;display:flex;justify-content:space-between;font-size:12.5px;color:rgba(248,245,239,.5);flex-wrap:wrap;gap:10px}

/* floating customer CTA */
.floatcta{position:fixed;right:26px;bottom:26px;z-index:60;opacity:0;transform:translateY(18px);pointer-events:none;transition:opacity .3s ease,transform .3s ease}
.floatcta.show{opacity:1;transform:translateY(0);pointer-events:auto}
.floatcta .btn{box-shadow:var(--lift);padding:15px 26px;font-size:15px}
.floatcta .btn:before{content:"";width:9px;height:9px;border-radius:50%;background:var(--teal);box-shadow:0 0 0 4px rgba(95,179,168,.25)}

@media(max-width:900px){
  .hero-grid{grid-template-columns:1fr;gap:38px}
  .hero h1{font-size:46px}
  .hero-media{order:-1}
  .pillars{grid-template-columns:1fr}
  .steps{grid-template-columns:1fr 1fr}
  .step .conn{display:none}
  .quality{grid-template-columns:1fr}
  .quality .media{min-height:220px;order:-1}
  .vendor .vhead{grid-template-columns:1fr}
  .vpillars{grid-template-columns:1fr}
  .vsteps{grid-template-columns:1fr 1fr}
  .fgrid{grid-template-columns:1fr 1fr}
  .navlinks{display:none}
}
@media(max-width:560px){
  .wrap{padding:0 16px}
  .hero h1{font-size:38px}
  .sec-head h2{font-size:30px}
  .final h2{font-size:32px}
  .vendor h2{font-size:30px}
  .steps,.vsteps,.fgrid{grid-template-columns:1fr}
  .floatcard{display:none}
  .navright .signin{display:none}
  .floatcta{right:14px;left:14px;bottom:14px}
  .floatcta .btn{width:100%}
}


/* Hero: the app's landing page (dark ink band), with the photo kept on the right */
.hero-app{background:var(--ink);color:var(--ivory);padding:76px 0 84px}
.hero-app h1.display{color:var(--ivory);font-weight:400;font-size:64px;line-height:1.05;margin:0}
.hero-app .lede{color:rgba(248,245,239,.7);font-size:18px;margin-top:24px;max-width:500px}
.hero-app .hero-cta{margin-top:36px}
.hero-note{margin-top:34px;font-size:14px;color:rgba(248,245,239,.5);max-width:480px}
.hero-note a{color:var(--champagne);text-decoration:underline;text-underline-offset:2px}
.hero-app .floatcard{color:var(--ink)}
.hero-app .hero-media .photo{box-shadow:0 22px 60px rgba(0,0,0,.35);border:1px solid rgba(248,245,239,.08)}
.hero-cards{display:grid;grid-template-columns:repeat(3,1fr);gap:22px;margin-top:84px}
.hero-card{border:1px solid rgba(248,245,239,.1);background:rgba(28,42,62,.4);border-radius:16px;padding:22px}
.hero-card h3{font-family:'Fraunces',Georgia,serif;font-weight:400;font-size:19px;color:var(--ivory);margin:0}
.hero-card p{margin-top:8px;font-size:14px;line-height:1.5;color:rgba(248,245,239,.6)}
@media(max-width:900px){
  .hero-app{padding:40px 0 56px}
  .hero-app h1.display{font-size:46px}
  .hero-cards{grid-template-columns:1fr;gap:14px;margin-top:48px}
}
@media(max-width:560px){
  .hero-app h1.display{font-size:40px}
}

.floatcta{opacity:1;transform:none;pointer-events:auto}
`;

